--
-- Name: increment_guide_reference_version_for_color_change_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_guide_reference_version_for_color_change_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE guides g
       SET reference_version = g.reference_version + 1
     WHERE EXISTS (
         SELECT 1
           FROM guide_step_product_links l
          WHERE l.guide_id = g.id
            AND l.color_id = NEW.id
     );
    RETURN NEW;
END;
$$;


