    CONSTRAINT ck_product_shade_colors_review CHECK (((review_status)::text = ANY (ARRAY[('AUTO_APPROVED'::character varying)::text, ('BELOW_THRESHOLD'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text]))),
    CONSTRAINT ck_product_shade_colors_source CHECK (((color_source)::text = ANY (ARRAY[('SOURCE_VALUE'::character varying)::text, ('SWATCH_CHIP'::character varying)::text, ('PRODUCT_PHOTO'::character varying)::text, ('WEB_PHOTO'::character varying)::text, ('LLM_ESTIMATE'::character varying)::text, ('SAMPLE'::character varying)::text]))),
    CONSTRAINT ck_product_shade_colors_source_pair CHECK (((source_item_id IS NULL) = (source_evidence_key IS NULL)))
);


