);


--
-- Name: product_shades; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_shades (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    name_normalized character varying(200) NOT NULL,
    sort_order integer NOT NULL,
    color_hex character varying(7),
    color_source character varying(30),
    color_estimated boolean,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    source_option_id character varying(200),
    CONSTRAINT ck_product_shades_color_all_or_none CHECK ((((color_hex IS NULL) AND (color_source IS NULL) AND (color_estimated IS NULL)) OR ((color_hex IS NOT NULL) AND (color_source IS NOT NULL) AND (color_estimated IS NOT NULL)))),
    CONSTRAINT ck_product_shades_color_hex CHECK (((color_hex)::text ~ '^#[0-9A-F]{6}$'::text))
);


