);


--
-- Name: products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.products (
    id uuid NOT NULL,
    brand character varying(100) NOT NULL,
    name character varying(200) NOT NULL,
    brand_normalized character varying(200) NOT NULL,
    name_normalized character varying(400) NOT NULL,
    category_code character varying(20) NOT NULL,
    type_code character varying(40) NOT NULL,
    source character varying(100),
    source_product_id character varying(100),
    source_url character varying(1000),
    collected_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    image_url character varying(1000),
    sale_status character varying(20),
    name_compact character varying(400) GENERATED ALWAYS AS (replace((name_normalized)::text, ' '::text, ''::text)) STORED,
    CONSTRAINT ck_products_sale_status CHECK (((sale_status)::text = ANY (ARRAY[('ON_SALE'::character varying)::text, ('SOLD_OUT'::character varying)::text, ('MISSING'::character varying)::text])))
);


