--
-- Name: product_shade_colors increment_guide_reference_version_for_color_change; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER increment_guide_reference_version_for_color_change AFTER UPDATE OF color_hex, review_status ON public.product_shade_colors FOR EACH ROW WHEN (((
        CASE
            WHEN ((old.review_status)::text = ANY (ARRAY[('AUTO_APPROVED'::character varying)::text, ('APPROVED'::character varying)::text])) THEN old.color_hex
            ELSE NULL::character varying
        END)::text IS DISTINCT FROM (
        CASE
            WHEN ((new.review_status)::text = ANY (ARRAY[('AUTO_APPROVED'::character varying)::text, ('APPROVED'::character varying)::text])) THEN new.color_hex
            ELSE NULL::character varying
        END)::text)) EXECUTE FUNCTION public.increment_guide_reference_version_for_color_change_fn();


